triangle-kind:
: main
  (forall ρ; ρ a:Int^many b:Int^many c:Int^many -- ρ kind:Int^many)
  sort3 kind;

: kind
  (forall ρ; ρ x:Int^many y:Int^many z:Int^many -- ρ k:Int^many)
  locals { x y z } {
    x 0 prim =
    [ 0 ]
    [ z x y prim + prim <
      [ x z prim = [ 1 ] [ x y prim = y z prim = or2 [ 2 ] [ 3 ] if ] if ]
      [ 0 ] if ] if
  };

: or2
  (forall ρ; ρ p:Bool^many q:Bool^many -- ρ r:Bool^many)
  [ drop true ] [ ] if;

: sort3
  (forall ρ; ρ a:Int^many b:Int^many c:Int^many -- ρ lo:Int^many mid:Int^many hi:Int^many)
  locals { a b c } {
    a b min2 c min2
    a b prim + c prim + a b min2 c min2 prim - a b max2 c max2 prim -
    a b max2 c max2
  };

: min2
  (forall ρ; ρ a:Int^many b:Int^many -- ρ m:Int^many)
  locals { a b } { a b prim < [ a ] [ b ] if };

: max2
  (forall ρ; ρ a:Int^many b:Int^many -- ρ m:Int^many)
  locals { a b } { a b prim < [ b ] [ a ] if };

divmod:
: main
  (forall ρ; ρ a:Int^many b:Int^many -- ρ q:Int^many r:Int^many)
  divmod;

: divmod
  (forall ρ; ρ a:Int^many b:Int^many -- ρ q:Int^many r:Int^many)
  [ 0 swap ] dip dm-loop;

: dm-loop
  (forall ρ; ρ q:Int^many r:Int^many b:Int^many -- ρ q2:Int^many r2:Int^many)
  locals { q r b } { r b prim < [ q r ] [ q 1 prim + r b prim - b dm-loop ] if };

isqrt:
: main
  (forall ρ; ρ n:Int^many -- ρ r:Int^many)
  0 isqrt-loop;

: isqrt-loop
  (forall ρ; ρ n:Int^many r:Int^many -- ρ s:Int^many)
  locals { n r } { n r 1 prim + dup prim * prim < [ r ] [ n r 1 prim + isqrt-loop ] if };

is-prime:
: main
  (forall ρ; ρ n:Int^many -- ρ r:Bool^many)
  dup 2 prim < [ drop false ] [ 2 trial ] if;

: trial
  (forall ρ; ρ n:Int^many d:Int^many -- ρ r:Bool^many)
  locals { n d } {
    n d d prim * prim < [ true ] [ n d mod 0 prim = [ false ] [ n d 1 prim + trial ] if ] if
  };

: mod
  (forall ρ; ρ a:Int^many b:Int^many -- ρ r:Int^many)
  divmod swap drop;

: divmod
  (forall ρ; ρ a:Int^many b:Int^many -- ρ q:Int^many r:Int^many)
  [ 0 swap ] dip dm-loop;

: dm-loop
  (forall ρ; ρ q:Int^many r:Int^many b:Int^many -- ρ q2:Int^many r2:Int^many)
  locals { q r b } { r b prim < [ q r ] [ q 1 prim + r b prim - b dm-loop ] if };

digit-sum:
: main
  (forall ρ; ρ n:Int^many -- ρ r:Int^many)
  0 swap ds-loop;

: ds-loop
  (forall ρ; ρ acc:Int^many n:Int^many -- ρ r:Int^many)
  locals { acc n } {
    n 0 prim = [ acc ] [ n 10 divmod acc prim + swap ds-loop ] if
  };

: divmod
  (forall ρ; ρ a:Int^many b:Int^many -- ρ q:Int^many r:Int^many)
  [ 0 swap ] dip dm-loop;

: dm-loop
  (forall ρ; ρ q:Int^many r:Int^many b:Int^many -- ρ q2:Int^many r2:Int^many)
  locals { q r b } { r b prim < [ q r ] [ q 1 prim + r b prim - b dm-loop ] if };

lcm:
: main
  (forall ρ; ρ a:Int^many b:Int^many -- ρ r:Int^many)
  locals { a b } { a b prim * a b gcd divmod drop };

: gcd
  (forall ρ; ρ a:Int^many b:Int^many -- ρ r:Int^many)
  locals { a b } { a b prim = [ a ] [ a b prim < [ a b a prim - gcd ] [ a b prim - b gcd ] if ] if };

: divmod
  (forall ρ; ρ a:Int^many b:Int^many -- ρ q:Int^many r:Int^many)
  [ 0 swap ] dip dm-loop;

: dm-loop
  (forall ρ; ρ q:Int^many r:Int^many b:Int^many -- ρ q2:Int^many r2:Int^many)
  locals { q r b } { r b prim < [ q r ] [ q 1 prim + r b prim - b dm-loop ] if };

allocate:
: main
  (forall ρ; ρ remaining:Int^many requested:Int^many whole:Bool^many -- ρ left:Int^many allocated:Int^many reason:Int^many)
  locals { rem req whole } {
    req rem prim < req rem prim = or2
    [ rem req prim - req 0 ]
    [ rem 0 prim = [ 0 0 2 ] [ whole [ rem 0 3 ] [ 0 rem 1 ] if ] if ] if
  };

: or2
  (forall ρ; ρ p:Bool^many q:Bool^many -- ρ r:Bool^many)
  [ drop true ] [ ] if;
